  1	// A LIFO queue (aka a stack) with limited capacity.
  2	class LimitedStack{
  3	 
  4	      var capacity : int; // capacity, max number of elements allowed on the stack.
  5	      var arr : array<int>; // contents of stack.
  6	      var top : int; // The index of the top of the stack, or -1 if the stack is empty
  7	
  8	      // This predicate express a class invariant: All objects of this calls should satisfy this.
  9	      predicate Valid()
 10	      reads this;
 11	      {
 12	        arr != null && capacity > 0 && capacity == arr.Length &&  top >= -1 && top < capacity 
 13	      }
 14	
 15	      predicate Empty()
 16	      reads this`top;
 17	      {
 18	            top == -1
 19	      }
 20	
 21	      predicate Full()
 22	      reads this`top, this`capacity;
 23	      {
 24	        top == (capacity - 1)
 25	      }
 26	  
 27	      method Init(c : int)
 28	      modifies this;
 29	      requires c > 0
 30	      ensures Valid() && Empty() && c == capacity
 31	      ensures fresh(arr); // ensures arr is a newly created object.
 32	      // Additional post-condition to be given here!
 33	      {
 34	        capacity := c;
 35	        arr := new int[c];
 36	        top := -1;
 37	      }
 38	
 39	
 40	      
 41	      method isEmpty() returns (res : bool)
 42	      ensures res == Empty()
 43	      {
 44	        if(top == -1)
 45	        { return true; }
 46	        else {
 47	              return false;
 48	        }
 49	      }
 50	
 51	
 52	
 53	      // Returns the top element of the stack, without removing it.
 54	      method Peek() returns (elem : int) 
 55	      requires Valid() && !Empty()
 56	      ensures elem == arr[top]
 57	      {
 58	            return arr[top]; 
 59	      }
 60	
 61	
 62	
 63	      // Pushed an element to the top of a (non full) stack. 
 64	      method Push(elem : int)
 65	      modifies this`top, this.arr 
 66	      requires Valid()
 67	      requires !Full() 
 68	      ensures Valid() && top == old(top) + 1 && arr[top] == elem
 69	      ensures !old(Empty()) ==> forall i : int :: 0 <= i <= old(top)  ==> arr[i] == old(arr[i]);
 70	      {
 71	            top := top + 1;
 72	            arr[top] := elem;
 73	      }
 74	
 75	      // Pops the top element off the stack.
 76	
 77	      method Pop() returns (elem : int)
 78	      modifies   this`top
 79	      requires Valid() && !Empty()  
 80	      ensures Valid()  && top == old(top) - 1 
 81	      ensures elem == arr[old(top)] 
 82	      {
 83	            elem := arr[top];
 84	            top := top - 1;
 85	            return elem;
 86	      }
 87	
 88	 
 89	      method Shift()
 90	      requires Valid() && !Empty();
 91	      ensures Valid();
 92	      ensures forall i : int :: 0 <= i < capacity - 1 ==> arr[i] == old(arr[i + 1]);
 93	      ensures top == old(top) - 1;
 94	      modifies this.arr, this`top;
 95	      {
 96	        var i : int := 0;
 97	        while (i < capacity - 1 )
 98	        invariant 0 <= i < capacity;
 99	        invariant top == old(top);
100	        invariant forall j : int :: 0 <= j < i ==> arr[j] == old(arr[j + 1]);
101	        invariant forall j : int :: i <= j < (capacity) - 1 ==> arr[j] == old(arr[j]);
102	        {
103	          arr[i] := arr[i + 1];
104	          i := i + 1;
105	        }
106	        top := top - 1;
107	      }
108	
109	 
110	      //Push onto full stack, oldest element is discarded.
111	      method Push2(elem : int)
112	      modifies this.arr, this`top
113	      requires Valid()
114	      ensures Valid() && !Empty() 
115	      ensures arr[top] == elem
116	      ensures old(!Full()) ==> top == old(top) + 1 && old(Full()) ==> top == old(top)
117	      ensures ((old(Full()) ==> arr[capacity - 1] == elem)  && (old(!Full()) ==> (top == old(top) + 1 && arr[top] == elem) ))
118	      ensures old(Full()) ==> forall i : int :: 0 <= i < capacity - 1 ==> arr[i] == old(arr[i + 1]);
119	      {
120	            if(top == capacity - 1){
121	                  Shift();
122	                  top := top + 1;
123	                  arr[top] := elem;
124	            }
125	            else{
126	                  top := top + 1;
127	                  arr[top] := elem;
128	            }
129	      }
130	 
131	
132	 
133	
134	// When you are finished,  all the below assertions should be provable. 
135	// Feel free to add extra ones as well.
136	      method Main(){
137	           var s := new LimitedStack;
138	           s.Init(3);
139	
140	           assert s.Empty() && !s.Full(); 
141	
142	           s.Push(27);
143	           assert !s.Empty();
144	
145	           var e := s.Pop();
146	           assert e == 27;
147	
148	           assert s.top == -1; 
149	           assert s.Empty() && !s.Full(); 
150	           
151	           s.Push(5);
152	
153	           assert s.top == 0;
154	           assert s.capacity == 3;
155	           s.Push(32);
156	           s.Push(9);
157	           assert s.Full();
158	
159	           assert s.arr[0] == 5;
160	
161	           var e2 := s.Pop();
162	           
163	           assert e2 == 9 && !s.Full(); 
164	           assert s.arr[0] == 5;
165	
166	           s.Push(e2);
167	           s.Push2(99);
168	
169	           var e3 := s.Peek();
170	           assert e3 == 99;
171	           assert s.arr[0] == 32;
172	                     
173	       }
174	
175	}
